def solve(nums):
    if not nums:
        return 0

    nums.sort()
    longest_run = 1
    current_run = 1

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1] + 1:
            current_run += 1
            longest_run = max(longest_run, current_run)
        else:
            current_run = 1

    return longest_run
